arguments.command:
python3 -c "
from collections import Counter
import re

c = Counter()
with open('auth.log') as f:
    for line in f:
        if 'Failed password' in line:
            m = re.search(r'from (\S+) port', line)
            if m:
                c[m.group(1)] += 1

for ip, count in c.most_common(5):
    print(ip, count)
"

